const d = $json.output ?? $json;
const fails = [];
const num = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);
const near = (a, b) => Math.abs(a - b) < 0.02;

const net = num(d.net), vat = num(d.vat), gross = num(d.gross);

for (const f of ['supplier', 'invoice_number', 'issue_date']) {
  if (!d[f]) fails.push('missing ' + f);
}
if (net === null) fails.push('net unreadable');
if (gross === null) fails.push('gross unreadable');

if (net !== null && vat !== null && gross !== null && !near(net + vat, gross)) {
  fails.push('net + VAT does not equal gross');
}

if (Array.isArray(d.line_items) && d.line_items.length && net !== null) {
  const sum = d.line_items.reduce((t, li) => t + (num(li.amount) ?? 0), 0);
  if (!near(sum, net)) fails.push('line items do not sum to net');
}

if (d.vat_rate != null && ![0, 5, 20].includes(Number(d.vat_rate))) {
  fails.push('VAT rate ' + d.vat_rate + '% is not a UK rate');
}

if (gross !== null && gross < 0) fails.push('negative total, looks like a credit note');

return { json: { ...d, ok: fails.length === 0, problems: fails.join('; ') || null, source_email: $('New Invoice Email').item.json.id } };
